local function beast(ctx,e)for _,t in ipairs(ctx:card_definition(ctx:entity(e).card_id).tags or{})do if t=="beast"or t=="all"then return true end end return false end
return {api_version=1,id="EX1_549",name="Bestial Wrath",text="Give a friendly Beast +2 Attack and <b>Immune</b> this turn.",set="EXPERT1",type="spell",class="hunter",rarity="epic",cost=1,target_mode="required",targets=function(ctx,self)local r={};for _,e in ipairs(ctx:friendly_minions(self))do if beast(ctx,e)then r[#r+1]=e end end;return r end,on_play=function(ctx,self,target)ctx:buff_until_end_of_turn(target,2,0);ctx:grant_keyword_until_end_of_turn(target,"immune")end}
